import type { TurretConfig } from '../Config/TurretConfig';
import { Plane } from './Plane';

export class Turret extends Plane {

    /** 所属 Boss 的 id */
    public ownerId = 0;

    /** 配置（只读） */
    public config: TurretConfig = null!;

    /** 当前炮口朝向（度）。TurretAimSystem 写，FireSystem 读 */
    public aimAngle = 0;

    /** oscillate 模式相位（弧度） */
    public oscPhase = 0;

    /** 开火冷却累积（秒）。FireSystem 写 */
    public cooldownTimer = 0;

    /** 当前是否被编排允许开火。TurretScheduleSystem 写 */
    public active = false;

    constructor() {
        super('turret');
    }
    
}